-- Benchmark host bookkeeping deliberately survives loads; these are measured workload writes,
-- never netplay inputs. Configuration is generated by tools/bench/run.py.
local config_text, why = gd.mod_read('scripts/config.lua')
assert(config_text, why)
local cfg = assert(load(config_text, '@bench/config.lua', 't', {}))()
math.randomseed(cfg.seed)
local state = {complete=false, frames=0, roster={}, features={}, events={}, legacy_samples={}, seed=cfg.seed}
local stress_text=gd.mod_read('scripts/stress.lua')
local stress=stress_text and assert(load(stress_text,'@bench/stress.lua','t',_ENV))() or nil
local mission, mission_env
local begun, measured, finished = false, false, false
local allowed = {camera_params=true,contact_trace=true,contact_overlay=true,spawn_enemy=true,
  shader_load=true,post_add=true,fighter_shader=true,stage_shader=true,model_load=true,
  model_instance=true,model_transform=true,stage_hide=true,teleport=true,savestate=true,
  loadstate=true,fighter_bench=true,fighter_call=true,rewind_test=true,debug_stage=true}
local function quote(s)
  return '"'..s:gsub('[%z\1-\31\\"]',function(c)
    if c=='"' then return '\\"' elseif c=='\\' then return '\\\\' end
    return ('\\u%04x'):format(string.byte(c))
  end)..'"'
end
local function json(v)
  if type(v)=='string' then return quote(v) end
  if type(v)=='number' or type(v)=='boolean' then return tostring(v) end
  if type(v)~='table' then return 'null' end
  local out={}
  if #v>0 then for _,x in ipairs(v) do out[#out+1]=json(x) end;return '['..table.concat(out,',')..']' end
  for k,x in pairs(v) do out[#out+1]=quote(tostring(k))..':'..json(x) end
  table.sort(out);return '{'..table.concat(out,',')..'}'
end
local function save()
  local ok,err=gd.data_write_atomic('status.json',json(state))
  if not ok then gd.log('bench status write failed: '..tostring(err)) end
end
local function feature(name,status,reason)
  state.features[#state.features+1]={feature=name,status=status,reason=reason or ''}
  gd.log('bench '..name..': '..status..' '..tostring(reason or ''))
end
local function invoke(step)
  if step.api=='mission_command' then
    if not mission then feature(step.feature,'refused','mission runtime unavailable');return false end
    local ok,value,err=pcall(mission.command,mission,(step.args or {})[1])
    local applied=ok and value and not mission.pending
    feature(step.feature,applied and 'applied' or 'refused',applied and '' or tostring(ok and (err or 'waiting for controllable fighter') or value))
    return applied
  end
  if not allowed[step.api] or type(gd[step.api])~='function' then
    feature(step.feature,'unsupported','API unavailable or not in benchmark allowlist: '..tostring(step.api));return false
  end
  local ok,value,err=pcall(gd[step.api],table.unpack(step.args or {}))
  local success=ok and value~=false and not (value==nil and err~=nil)
  feature(step.feature,success and 'applied' or 'refused',success and '' or tostring(ok and err or value))
  return success
end
local enemies={}
local function refill_enemies()
  local live={}
  for _,h in ipairs(enemies) do if gd.enemy_alive(h) then live[#live+1]=h end end
  enemies=live
  local cap=cfg.enemy_cap or 0
  for i=#enemies+1,cap do
    local h,err=gd.spawn_enemy('goomba',(i%8-4)*12,30+math.floor(i/8)*12)
    if not h then feature('item_enemies_cap','refused',tostring(err));break end
    enemies[#enemies+1]=h
  end
  state.enemy_count=#enemies
end
local function begin()
  for i=1,#cfg.roster do
    local p=gd.player(i)
    if not p then return end -- no claimed admission until every requested primary exists
    state.roster[i]={slot=i,name=p.char_name or tostring(p.char),char=p.char,
      control=i<=4 and 'human_script' or 'cpu_virtual_script'}
  end
  begun=true
  if cfg.mission_stress then
    local text,err=gd.mod_read('scripts/mission_bundle.lua')
    if text then
      mission_env=setmetatable({},{__index=_ENV})
      local fn,parse=load(text,'@bench/mission_bundle.lua','t',mission_env)
      local ok,value=pcall(function() assert(fn,parse);return fn() end)
      if ok then mission=value else feature('mission_runtime','refused',tostring(value)) end
    else feature('mission_runtime','refused',tostring(err)) end
    if mission and cfg.mission_preparation and cfg.mission_preparation.ok then
      invoke{feature='missions_generated_maze',api='mission_command',args={'play '..cfg.mission_preparation.name}}
    else feature('missions_generated_maze','refused',cfg.mission_preparation and cfg.mission_preparation.reason or 'maze preparation unavailable') end
  end
  for i=5,#cfg.roster do
    local ok,err=pcall(gd.cpu_mode,i,'stand')
    feature('cpu_mode_slot_'..i,ok and 'applied' or 'refused',ok and '' or tostring(err))
  end
  if stress then stress.setup(gd,cfg,feature) end
  if cfg.scenario=='hitch_worst' then
    feature('first_use_shader_effect_coverage','partial','project sample post/surface/material/clank shaders; ported fighter neutral and directional B first-use attempts when discovered; no universal every-effect invocation API')
  end
  if cfg.ported_candidate then
    local actual=state.roster[2].name:lower():gsub('[^a-z0-9]','')
    feature('ported_geno_fighter',actual==cfg.ported_candidate.token and 'applied' or 'refused','requested '..cfg.ported_candidate.name..'; actual '..state.roster[2].name)
  end
  local configured={}
  for _,entry in ipairs(state.features) do configured[entry.feature]=true end
  for _,step in ipairs(cfg.setup or {}) do configured[step.feature]=true;invoke(step) end
  for _,step in ipairs(cfg.events or {}) do configured[step.feature]=true end
  for _,name in ipairs(cfg.features or {}) do
    if not configured[name] then feature(name,'unsupported','requires explicit asset/setup/event configuration; not simulated') end
  end
  if cfg.mission_generator_available then
    feature('maze_generator_discovery','available','source generator exists; see preparation and runtime results')
  end
  if (cfg.enemy_cap or 0)>0 then refill_enemies();feature('item_enemies_cap',#enemies==cfg.enemy_cap and 'applied' or 'partial',tostring(#enemies)..' live') end
  save()
end
function on_frame_pre()
  if finished then return end
  local match=gd.match()
  if not match or not match.active then return end
  if not begun then begin();if not begun then return end end
  if not measured then return end
  for i=1,#cfg.roster do
    local phase=(state.frames+i*11)%120
    local sample
    if phase<30 then sample={buttons='A',x=i%2==0 and -65 or 65}
    elseif phase<60 then sample={buttons='B',y=(i%3-1)*80}
    elseif phase<90 then sample={buttons='L',l=255}
    else sample={buttons='X',x=i%2==0 and 45 or -45} end
    if cfg.scenario=='hitch_worst' then
      sample={}
      if cfg.ported_candidate and i==2 then
        local frame=state.frames+1
        if frame>=920 and frame<926 then sample={y=-110}
        elseif frame>=926 and frame<941 then sample={buttons='B'}
        elseif frame>=980 and frame<986 then sample={y=110}
        elseif frame>=986 and frame<1001 then sample={buttons='B'}
        elseif frame>=1040 and frame<1046 then sample={x=110}
        elseif frame>=1046 and frame<1061 then sample={buttons='B'}
        elseif frame>=1100 and frame<1115 then sample={buttons='B'} end
      end
    end -- isolate one-off spikes; bench/call requires a safe neutral fighter
    gd.input(i,sample,1)
  end
  if cfg.scenario=='hitch_worst' and cfg.ported_candidate then
    local labels={[926]='ported_down_special_first_use',[986]='ported_up_special_first_use',[1046]='ported_side_special_first_use',[1100]='ported_neutral_special_first_use'}
    local label=labels[state.frames+1]
    if label then state.events[#state.events+1]={feature=label,logic_frame=state.frames+1,requested=true} end
  end
  if stress then
    stress.tick(gd,cfg,feature,state.frames+1)
    if cfg.scenario=='hitch_worst' then
      for _,event in ipairs(stress.hitch_events) do
        if event.frame==state.frames+1 then state.events[#state.events+1]={feature=event.feature,logic_frame=event.frame,requested=true} end
      end
    end
  end
  for _,event in ipairs(cfg.events or {}) do
    if event.frame==state.frames+1 then
      local ok=invoke(event)
      state.events[#state.events+1]={feature=event.feature,logic_frame=event.frame,applied=ok}
    end
  end
end
function on_frame()
  if finished or not begun then return end
  if not measured then
    state.measurement_reset=gd.prof and gd.prof('reset') or false
    if not state.measurement_reset then feature('measurement_reset','unsupported','gd.prof unavailable; profile includes startup') end
    measured=true;return -- setup/warmup frame is excluded from requested logic frames
  end
  if mission then
    local ok,err=pcall(mission.frame,mission)
    if not ok and not state.mission_frame_error then state.mission_frame_error=tostring(err);feature('mission_frame','refused',tostring(err)) end
    local c=mission.current
    local chunk=c and c.stream and c.stream.current
    local id=chunk and (chunk.id or chunk.name)
    if id and id~=state.current_chunk then
      state.events[#state.events+1]={feature='chunk_crossing',logic_frame=state.frames+1,chunk=tostring(id),applied=true}
      state.current_chunk=id
    end
    state.mission_active=c~=nil;state.mission_pending=mission.pending~=nil
  end
  local perf=gd.perf(1)
  local latest=perf and perf.frames and perf.frames[#perf.frames]
  if latest then
    state.legacy_samples[#state.legacy_samples+1]={logic_ms=latest.logic_ms,gx_ms=latest.gx_ms,total_ms=latest.total_ms,worker_ms=latest.worker_ms}
    for _,event in ipairs(state.events) do
      if state.frames+1>=event.logic_frame and state.frames+1<=event.logic_frame+3 then
        if not event.worst_observed_present or (latest.total_ms or 0)>(event.worst_observed_present.total_ms or 0) then
          event.worst_observed_present=latest
          event.metric_scope='latest presented sample during 4 callback window; asynchronous, inspect trace for attribution'
        end
      end
    end
  end
  state.frames=state.frames+1
  if cfg.scenario=='hitch_worst' and gd.prof then
    for _,event in ipairs(state.events) do
      if event.logic_frame+4==state.frames then
        local ok=gd.prof('trace 8')
        if ok then
          state.trace_sequence=(state.trace_sequence or 0)+1
          state.trace_capture={sequence=state.trace_sequence,feature=event.feature,logic_frame=event.logic_frame}
          save()
        end
      end
    end
  end
  if cfg.enemy_cap and state.frames%30==0 then refill_enemies() end
  if state.frames>=cfg.frames then
    finished=true;state.complete=true
    if gd.prof then
      local ok,err=gd.prof('report');state.report_ok=ok;state.report_reason=err
    end
    for i=1,#cfg.roster do gd.release(i) end
    state.perf=gd.perf(1)
    if type(gd.rollbacks)=='function' then state.rollbacks=gd.rollbacks() end
    save();gd.quit()
  elseif state.frames%120==0 then save() end
end
function on_match_end()
  if not finished then state.reason='match ended before requested logic frames';save();gd.quit() end
end

function on_draw() if mission then mission:draw() end end
function on_loadstate() if mission then mission:stop('benchmark state load') end end
function on_unload() if mission then mission:stop('benchmark unload') end end

function on_clank(event) if stress then stress.clank(gd,cfg,feature,event);state.clank_events=stress.clanks or 0 end end
